js-mh2-life-step.alternative:
const nextGeneration = grid => grid.map((line, row) => {
  const cells = [...line].map((cell, column) => {
    let count = 0;
    for (let dr = -1; dr <= 1; dr++) {
      for (let dc = -1; dc <= 1; dc++) {
        if (dr === 0 && dc === 0) continue;
        if (grid[row + dr]?.[column + dc] === "#") count++;
      }
    }
    if (count === 3 || (cell === "#" && count === 2)) return "#";
    return ".";
  });
  return cells.join("");
});

