js-mh2-folder-tree.alternative:
const printTree = paths => {
  const root = Object.create(null);
  for (const path of paths) {
    const parts = path.split("/");
    const file = parts.pop();
    const folder = parts.reduce((at, name) => at[name] ??= Object.create(null), root);
    folder[file] = null;
  }
  const linesOf = (folder, prefix) => {
    const names = Object.keys(folder);
    const entries = [...names.filter(name => folder[name] !== null).sort(), ...names.filter(name => folder[name] === null).sort()];
    return entries.flatMap((name, i) => {
      const last = i === entries.length - 1;
      const line = prefix + (last ? "└── " : "├── ") + name;
      return folder[name] === null ? [line] : [line, ...linesOf(folder[name], prefix + (last ? "    " : "│   "))];
    });
  };
  return [".", ...linesOf(root, "")];
};

