js-mh-deep-equal.wrong-skips-holes:
const deepEqual = (a, b) => {
  if (Object.is(a, b)) return true; // primitives, NaN, and the same object twice
  // From here on both must be objects, and typeof null is "object" too.
  if (typeof a !== "object" || typeof b !== "object" || a === null || b === null) return false;
  if (Array.isArray(a) !== Array.isArray(b)) return false;
  if (Array.isArray(a)) {
    return a.length === b.length && a.every((item, i) => deepEqual(item, b[i]));
  }
  const keys = Object.keys(a);
  // Counting keys alone would let { a: undefined } equal { b: undefined }.
  return keys.length === Object.keys(b).length &&
    keys.every(key => Object.hasOwn(b, key) && deepEqual(a[key], b[key]));
};

js-mh2-seats-together.alternative:
const bestSeats = (rows, count) => {
  const wanted = ".".repeat(count);
  const middleRow = (rows.length - 1) / 2;
  const blocksIn = (line, row) => {
    const found = [];
    let seat = line.indexOf(wanted);
    while (seat !== -1) {
      found.push({ row, seat, rowDistance: Math.abs(row - middleRow), seatDistance: Math.abs(seat + (count - 1) / 2 - (line.length - 1) / 2) });
      seat = line.indexOf(wanted, seat + 1);
    }
    return found;
  };
  const [best] = rows.flatMap(blocksIn).sort((a, b) => a.rowDistance - b.rowDistance || a.seatDistance - b.seatDistance || a.row - b.row || a.seat - b.seat);
  return best ? { row: best.row, seat: best.seat } : null;
};

