};

js-mh-sudoku-check.alternative:
const isValidSudoku = board => {
  if (!Array.isArray(board) || board.length !== 9 || !Array.from({ length: 9 }, (_, i) => i).every(i => Object.hasOwn(board, i) && Array.isArray(board[i]) && board[i].length === 9)) return false;
  const rowSets = Array.from({ length: 9 }, () => new Set());
  const colSets = Array.from({ length: 9 }, () => new Set());
  const boxSets = Array.from({ length: 9 }, () => new Set());
  for (let r = 0; r < 9; r++) {
    for (let c = 0; c < 9; c++) {
      const digit = board[r][c];
      if (!Object.hasOwn(board[r], c) || !Number.isInteger(digit) || digit < 0 || digit > 9) return false;
      if (digit === 0) continue;
      const box = Math.floor(r / 3) * 3 + Math.floor(c / 3);
      if (rowSets[r].has(digit) || colSets[c].has(digit) || boxSets[box].has(digit)) return false;
      rowSets[r].add(digit);
      colSets[c].add(digit);
      boxSets[box].add(digit);
    }
  }
  return true;
};

